<?php defined('_JEXEC') or die; $standing=is_array($workspace['standings']??null)?$workspace['standings']:null; ?>
<div class="dh-page-heading"><div><p class="dh-eyebrow">THE WIDER PICTURE</p><h1><?= $standing ? $escape($standing['competition']??'Competition') : 'Competitions' ?></h1><p class="dh-lead"><?= $standing ? $escape($standing['season']??'Retained season') : 'Explore the leagues and seasons present in your source data.' ?></p></div><?php if ($standing): ?><a class="dh-button" href="<?= $escape($route(['section'=>'competitions'])) ?>">← All competitions</a><?php endif; ?></div>
<?php if ($standing): ?>
  <div class="dh-actions dh-section-actions"><a class="dh-button dh-button-primary" href="<?= $escape($route(['section'=>'matches','competition'=>$filters['competition']??''])) ?>">Browse competition matches</a><span class="dh-badge"><?= !empty($standing['official']) ? 'Provider standing' : 'Calculated from retained results' ?></span></div>
  <section class="dh-panel"><h2>Standings</h2><p class="dh-muted"><?= $escape($standing['label']??'Calculated from available final results') ?></p><?php if (empty($standing['items'])): ?><p class="dh-empty"><?= $escape($standing['reason']??$standing['label']??'No supported standing is available for this competition.') ?></p><?php else: ?><div class="dh-table-wrap" role="region" aria-label="Competition standings" tabindex="0"><table class="dh-table dh-standings"><caption><?= $escape($standing['label']??'Retained results table') ?></caption><thead><tr><th scope="col">Position</th><th scope="col">Team</th><th scope="col"><abbr title="Played">P</abbr></th><th scope="col"><abbr title="Won">W</abbr></th><th scope="col"><abbr title="Drawn">D</abbr></th><th scope="col"><abbr title="Lost">L</abbr></th><th scope="col"><abbr title="Goals for">GF</abbr></th><th scope="col"><abbr title="Goals against">GA</abbr></th><th scope="col">Points</th></tr></thead><tbody><?php foreach ($standing['items'] as $index=>$row): ?><tr><td><?= (int)$index+1 ?></td><th scope="row"><a href="<?= $escape($route(['section'=>'teams','team_id'=>$row['team_id']??''])) ?>"><?= $escape($row['team']??'Unknown team') ?></a></th><?php foreach (['played','won','drawn','lost','goals_for','goals_against','points'] as $key): ?><td><?= $escape($row[$key]??'—') ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><p class="dh-timestamp">Calculated as of <?= $escape($date($standing['as_of']??null,true)) ?> · Source <?= $escape($standing['source_id']??'Not recorded') ?></p></section>
  <?php if (!empty($standing['limitations'])): ?><aside class="dh-note"><div><h2>Read this table with its limits</h2><ul><?php foreach ($standing['limitations'] as $limitation): ?><li><?= $escape($limitation) ?></li><?php endforeach; ?></ul></div></aside><?php endif; ?>
<?php else: ?>
  <?php $competitions=$items($workspace['competitions']??[]); if (!$competitions): ?><section class="dh-panel"><p class="dh-empty">No competitions are available in the retained data.</p></section><?php else: ?><div class="dh-entity-grid"><?php foreach ($competitions as $competition): ?><a class="dh-entity-card" href="<?= $escape($route(['section'=>'competitions','competition'=>$competition['id']??''])) ?>"><span class="dh-competition-mark" aria-hidden="true">◇</span><span><strong><?= $escape($competition['name']??'Unknown competition') ?></strong><small><?= $escape($competition['season']??'Season not supplied') ?></small></span><span class="dh-arrow" aria-hidden="true">↗</span></a><?php endforeach; ?></div><?php endif; ?>
<?php endif; ?>
